//! 📑️ Writes explicit document styles, images and typed recursive blocks under one ownership budget.
use crate::standards::v1::subsets::document::schema::snapshot::{SemioDocumentSnapshot,DocStyle,DocImage,DocBlock,DocRun,RunStyle};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(crate) fn encode(snapshot:&SemioDocumentSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io::IoPayload,ValueError>{native_encoding::encode_admitted(encoding,"semio s.stdio.semio.document.dsl v1\n","s.stdio.semio.document.pack v1",control,|control|crate::standards::v1::subsets::document::io::sqlite::snapshot::admit_values(snapshot,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative,control),|writer,encoding|fields(snapshot,writer,encoding))}
fn boolean(value:bool,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.byte(if encoding==SnapshotEncoding::Binary{u8::from(value)}else{if value{b'1'}else{b'0'}})}
fn optional<T>(value:Option<&T>,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding,emit:impl FnOnce(&T,&mut Writer<'_,'_,'_>,SnapshotEncoding)->Result<(),ValueError>)->Result<(),ValueError>{match value{None=>if encoding==SnapshotEncoding::Binary{writer.byte(0)}else{writer.bytes(b"[0]")},Some(value)=>{if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"[1,")?;}emit(value,writer,encoding)?;writer.delimiter(b"]",encoding)}}}
fn optional_text(value:&Option<String>,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{optional(value.as_ref(),writer,encoding,|value,writer,encoding|writer.string(value,encoding))}
fn optional_number(value:Option<f64>,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{optional(value.as_ref(),writer,encoding,|value,writer,encoding|if encoding==SnapshotEncoding::Binary{writer.number(*value,encoding)}else{writer.integer(value.to_bits(),encoding)})}
fn run_style(value:&RunStyle,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;writer.delimiter(b"[",encoding)?;for(index,value)in [value.bold,value.italic,value.underline].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}boolean(value,writer,encoding)?;}writer.delimiter(b",",encoding)?;optional_number(value.size,writer,encoding)?;for value in [&value.font,&value.color,&value.link]{writer.delimiter(b",",encoding)?;optional_text(value,writer,encoding)?;}writer.delimiter(b"]",encoding)}
fn run(value:&DocRun,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.text,encoding)?;writer.delimiter(b",",encoding)?;run_style(&value.style,writer,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn block(value:&DocBlock,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding,depth:usize)->Result<(),ValueError>{
 if depth>=64{return Err(ValueError::new(ValueRefusalKind::DepthLimit,"Semio document native output exceeds depth64"))}let(binary,text)=match value{DocBlock::Paragraph{..}=>(0,b'P'),DocBlock::Heading{..}=>(1,b'H'),DocBlock::List{..}=>(2,b'L'),DocBlock::Table{..}=>(3,b'T'),DocBlock::Code{..}=>(4,b'C'),DocBlock::Quote{..}=>(5,b'Q'),DocBlock::Image{..}=>(6,b'I'),DocBlock::PageBreak=>(7,b'B')};writer.byte(if encoding==SnapshotEncoding::Binary{binary}else{text})?;writer.delimiter(b"[",encoding)?;
 match value{
 DocBlock::Paragraph{style_id,runs}=>{optional_text(style_id,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.list(runs,encoding,|writer,value|run(value,writer,encoding))?;},
 DocBlock::Heading{level,style_id,runs}=>{if encoding==SnapshotEncoding::Binary{writer.byte(*level)?;}else{writer.integer(u64::from(*level),encoding)?;}writer.delimiter(b",",encoding)?;optional_text(style_id,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.list(runs,encoding,|writer,value|run(value,writer,encoding))?;},
 DocBlock::List{ordered,items}=>{boolean(*ordered,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.list(items,encoding,|writer,value|{writer.delimiter(b"[",encoding)?;writer.list(&value.blocks,encoding,|writer,value|block(value,writer,encoding,depth+1))?;writer.delimiter(b"]",encoding)})?;},
 DocBlock::Table{rows}=>{writer.list(rows,encoding,|writer,row|{writer.delimiter(b"[",encoding)?;writer.list(&row.cells,encoding,|writer,cell|{writer.delimiter(b"[",encoding)?;writer.list(&cell.blocks,encoding,|writer,value|block(value,writer,encoding,depth+1))?;writer.delimiter(b"]",encoding)})?;writer.delimiter(b"]",encoding)})?;},
 DocBlock::Code{language,text}=>{optional_text(language,writer,encoding)?;writer.delimiter(b",",encoding)?;writer.string(text,encoding)?;},
 DocBlock::Quote{blocks}=>{writer.list(blocks,encoding,|writer,value|block(value,writer,encoding,depth+1))?;},
 DocBlock::Image{image_id,alt,width,height}=>{writer.string(image_id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(alt,encoding)?;writer.delimiter(b",",encoding)?;optional_number(*width,writer,encoding)?;writer.delimiter(b",",encoding)?;optional_number(*height,writer,encoding)?;},DocBlock::PageBreak=>{}
 }writer.delimiter(b"]",encoding)
}
fn style(value:&DocStyle,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.name,encoding)?;writer.delimiter(b",",encoding)?;optional_text(&value.based_on,writer,encoding)?;writer.delimiter(b"]",encoding)}
fn image(value:&DocImage,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&value.id,encoding)?;writer.delimiter(b",",encoding)?;writer.string(&value.mime,encoding)?;writer.delimiter(b",",encoding)?;writer.octets(&value.bytes,encoding)?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioDocumentSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nstyles=",encoding)?;writer.list(&snapshot.styles,encoding,|writer,value|style(value,writer,encoding))?;writer.delimiter(b"\nimages=",encoding)?;writer.list(&snapshot.images,encoding,|writer,value|image(value,writer,encoding))?;writer.delimiter(b"\nblocks=",encoding)?;writer.list(&snapshot.blocks,encoding,|writer,value|block(value,writer,encoding,0))}
